package br.com.gestao.product; import br.com.gestao.product.dto.*; import br.com.gestao.stock.dto.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController{private final ProductService service;public ProductController(ProductService s){service=s;} @GetMapping public List<Product> list(@RequestParam(required=false) String search){return service.list(search);} @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public Product create(@Valid @RequestBody ProductRequest q,Authentication a){return service.create(q,a.getName());} @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public Product update(@PathVariable Long id,@Valid @RequestBody ProductRequest q){return service.update(id,q);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable Long id){service.delete(id);} @PostMapping("/{id}/stock") @PreAuthorize("hasRole('ADMIN')") public Product stock(@PathVariable Long id,@Valid @RequestBody StockMovementRequest q,Authentication a){if(!id.equals(q.productId()))throw new IllegalArgumentException("Produto divergente");return service.move(id,q.type(),q.quantity(),q.note(),a.getName());}}
